//! Theme constants generated by `build.rs` from
//! `design-system/tokens/themes.json`.

include!(concat!(env!("OUT_DIR"), "/theme_tokens.rs"));

#[cfg(test)]
mod tests {
    use super::{ALL_THEMES, MODERN_DARK};

    #[test]
    fn modern_dark_matches_the_design_system() {
        assert_eq!(MODERN_DARK.name, "modern-dark");
        assert_eq!(MODERN_DARK.canvas, 0x010A_13FF);
        assert_eq!(MODERN_DARK.primary, 0xC8AA_6EFF);
        assert_eq!(MODERN_DARK.overlay, 0x010A_13CC);
        assert_eq!(MODERN_DARK.radius_small, 4);
        assert_eq!(MODERN_DARK.border_width, 1);
    }

    #[test]
    fn every_theme_is_generated() {
        let names = ALL_THEMES.map(|theme| theme.name);
        assert_eq!(
            names,
            [
                "modern-dark",
                "modern-light",
                "classic-dark",
                "classic-light"
            ]
        );
    }
}
